head.b:skin:
/* ==============================================================
   SAARTHI — a light, editorial Blogger theme
   --------------------------------------------------------------
   Original design system. No framework, no jQuery, no dark mode.

   >>> CUSTOMIZATION AREA (1 of 3) — THEME DESIGNER VARIABLES <<<
   The <Variable> tags below are read by Blogger and appear under
   Theme -> Customize -> Advanced. Change them there, or edit the
   "value" attribute here and re-upload the theme.
   ============================================================== */
/* Variable definitions
   =====================
   <Group description="Brand" selector="body">
     <Variable name="keycolor" description="Primary colour (nav, links, buttons)" type="color" default="#0d5f57" value="#0d5f57"/>
     <Variable name="accent.color" description="Accent colour (rules, badges, highlights)" type="color" default="#a63d2f" value="#a63d2f"/>
   </Group>
   <Group description="Page" selector="body">
     <Variable name="body.bg.color" description="Page background" type="color" default="#f4f6f4" value="#f4f6f4"/>
     <Variable name="body.text.color" description="Body text" type="color" default="#2b3634" value="#2b3634"/>
     <Variable name="link.color" description="Link colour" type="color" default="#0d5f57" value="#0d5f57"/>
   </Group>
   <Group description="Layout" selector=".st-container">
     <Variable name="content.width" description="Container width" type="length" default="1200px" value="1200px"/>
     <Variable name="card.radius" description="Corner radius" type="length" default="6px" value="6px"/>
   </Group>
*/

/* ============================== TOKENS ============================== */
:root {
  /* Values coming from Theme Designer (see block above) */
  --primary: $(keycolor);
  --accent: $(accent.color);
  --bg: $(body.bg.color);
  --text: $(body.text.color);
  --link: $(link.color);
  --container: $(content.width);
  --radius-md: $(card.radius);

  /* Derived tones — the static value is the fallback for browsers
     without color-mix(); the second line overrides when supported,
     so a Theme Designer colour change flows through the whole UI. */
  --primary-dark: #0a4a44;
  --primary-dark: color-mix(in srgb, var(--primary) 78%, #04100f);
  --primary-tint: #e6f1ef;
  --primary-tint: color-mix(in srgb, var(--primary) 9%, #ffffff);
  --primary-line: #cfe3e0;
  --primary-line: color-mix(in srgb, var(--primary) 22%, #ffffff);
  --accent-tint: #fbeceb;
  --accent-tint: color-mix(in srgb, var(--accent) 9%, #ffffff);

  /* Neutrals */
  --surface: #ffffff;
  --surface-2: #fafbfa;
  --surface-3: #f1f4f2;
  --ink: #16211f;
  --muted: #63706d;
  --faint: #8b9694;
  --border: #e2e7e4;
  --border-strong: #ccd5d1;
  --nav-bg: var(--primary-dark);
  --footer-bg: #0c3f3b;
  --footer-bg: color-mix(in srgb, var(--primary) 70%, #05201e);
  --footer-line: rgba(255, 255, 255, .14);
  --on-dark: #e9f2f0;
  --on-dark-muted: #a9c4bf;

  /* Radii derived from the Theme Designer value */
  --radius-sm: max(0px, calc(var(--radius-md) - 3px));
  --radius-lg: calc(var(--radius-md) + 8px);
  --radius-pill: 999px;

  /* Type */
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
    "Helvetica Neue", "Noto Sans", "Noto Sans Devanagari", Arial, sans-serif;
  --font-mono: ui-monospace, SFMono-Regular, Menlo, Consolas,
    "Liberation Mono", monospace;
  --fs-100: clamp(.8125rem, .79rem + .1vw, .875rem);
  --fs-200: clamp(.9375rem, .9rem + .18vw, 1rem);
  --fs-300: clamp(1.0625rem, 1rem + .3vw, 1.1875rem);
  --fs-400: clamp(1.25rem, 1.14rem + .55vw, 1.5rem);
  --fs-500: clamp(1.5rem, 1.3rem + 1vw, 2rem);
  --fs-600: clamp(1.75rem, 1.4rem + 1.7vw, 2.6rem);

  /* Space + elevation */
  --sp-1: 4px;
  --sp-2: 8px;
  --sp-3: 12px;
  --sp-4: 16px;
  --sp-5: 24px;
  --sp-6: 32px;
  --sp-7: 48px;
  --sp-8: 64px;
  --gap: clamp(16px, 3.2vw, 28px);
  --shadow-1: 0 1px 2px rgba(18, 33, 31, .05);
  --shadow-2: 0 4px 14px rgba(18, 33, 31, .08);
  --shadow-3: 0 14px 34px rgba(18, 33, 31, .13);
  --hairline: 1px solid var(--border);
  --tap: 44px;
  --nav-h: 50px;
  --ease: cubic-bezier(.2, .7, .3, 1);
}

/* ============================== RESET ============================== */
*,
*::before,
*::after { box-sizing: border-box; }

html {
  -webkit-text-size-adjust: 100%;
  scroll-behavior: smooth;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  font-size: var(--fs-200);
  line-height: 1.65;
  overflow-wrap: break-word;
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4, h5, h6 {
  color: var(--ink);
  line-height: 1.28;
  margin: 0 0 .5em;
  font-weight: 700;
  letter-spacing: -.011em;
  text-wrap: balance;
}

p { margin: 0 0 1em; }
p:last-child { margin-bottom: 0; }

a {
  color: var(--link);
  text-decoration: none;
  transition: color .18s var(--ease);
}
a:hover { color: var(--accent); }

img, svg, video { max-width: 100%; height: auto; display: block; }

ul, ol { margin: 0 0 1em; padding-left: 1.25em; }

button, input, select, textarea {
  font: inherit;
  color: inherit;
  margin: 0;
}

button { cursor: pointer; }

hr {
  border: 0;
  border-top: var(--hairline);
  margin: var(--sp-5) 0;
}

table {
  border-collapse: collapse;
  width: 100%;
}

:focus-visible {
  outline: 3px solid var(--primary);
  outline-offset: 2px;
  border-radius: 2px;
}

::selection {
  background: var(--primary-tint);
  color: var(--primary-dark);
}

/* Screen-reader-only helper */
.st-sr {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

.st-skip {
  position: absolute;
  left: var(--sp-3);
  top: -100px;
  z-index: 400;
  background: var(--primary-dark);
  color: #fff;
  padding: 12px 20px;
  border-radius: 0 0 var(--radius-sm) var(--radius-sm);
  font-weight: 600;
  transition: top .18s var(--ease);
}
.st-skip:focus {
  top: 0;
  color: #fff;
}

/* ============================== LAYOUT ============================== */
.st-container {
  width: 100%;
  max-width: var(--container);
  margin-inline: auto;
  padding-inline: var(--gap);
}

.st-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: var(--sp-6);
  align-items: start;
  padding-block: var(--sp-6) var(--sp-7);
}

@media (min-width: 900px) {
  .st-grid {
    grid-template-columns: minmax(0, 1fr) 316px;
    gap: 40px;
  }
}
@media (min-width: 1240px) {
  .st-grid { grid-template-columns: minmax(0, 1fr) 348px; gap: 48px; }
}

/* Body-level switches — see CUSTOMIZATION AREA (3) in the XML */
body.st-no-sidebar .st-grid { grid-template-columns: minmax(0, 1fr); }
body.st-no-sidebar .st-sidebar { display: none; }

.st-main { min-height: 60vh; }

/* ============================== PRIMITIVES ============================== */
.st-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: var(--tap);
  padding: 10px 20px;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  background: var(--primary);
  color: #fff;
  font-size: var(--fs-200);
  font-weight: 600;
  line-height: 1.2;
  text-align: center;
  transition: background .18s var(--ease), color .18s var(--ease),
    border-color .18s var(--ease), transform .12s var(--ease);
}
.st-btn:hover { background: var(--primary-dark); color: #fff; }
.st-btn:active { transform: translateY(1px); }

.st-btn--ghost {
  background: var(--surface);
  border-color: var(--border-strong);
  color: var(--ink);
}
.st-btn--ghost:hover {
  background: var(--surface-3);
  border-color: var(--primary);
  color: var(--primary-dark);
}

.st-btn--sm { min-height: 36px; padding: 7px 14px; font-size: var(--fs-100); }

.st-btn--block { width: 100%; }

.st-eyebrow {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 0 0 10px;
  color: var(--accent);
  font-size: var(--fs-100);
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
}
.st-eyebrow::before {
  content: "";
  flex: 0 0 auto;
  width: 30px;
  height: 3px;
  background: var(--accent);
}
.st-eyebrow--plain::before { display: none; }

.st-chip {
  display: inline-block;
  padding: 4px 9px;
  border: 1px solid var(--primary-line);
  border-radius: 3px;
  background: var(--primary-tint);
  color: var(--primary-dark);
  font-size: .6875rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  line-height: 1.5;
  transition: background .18s var(--ease), color .18s var(--ease);
}
a.st-chip:hover {
  background: var(--primary);
  border-color: var(--primary);
  color: #fff;
}

.st-chip--accent {
  background: var(--accent-tint);
  border-color: color-mix(in srgb, var(--accent) 26%, #ffffff);
  color: var(--accent);
}

.st-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 10px;
  color: var(--muted);
  font-size: var(--fs-100);
  line-height: 1.5;
}
.st-meta__dot { color: var(--border-strong); }
.st-meta a { color: var(--muted); }
.st-meta a:hover { color: var(--primary); }
.st-meta__author { font-weight: 600; color: var(--ink); }

.st-sec-head {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: 8px 20px;
  padding-bottom: 12px;
  margin-bottom: var(--sp-5);
  border-bottom: var(--hairline);
}
.st-sec-head h2 {
  margin: 0;
  font-size: var(--fs-400);
  letter-spacing: -.015em;
}
.st-sec-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding-bottom: 3px;
  font-size: var(--fs-100);
  font-weight: 600;
  white-space: nowrap;
}
.st-sec-link::after {
  content: "\2192";
  transition: transform .18s var(--ease);
}
.st-sec-link:hover::after { transform: translateX(3px); }

/* ============================== READING PROGRESS ============================== */
.st-progress {
  position: fixed;
  inset: 0 0 auto 0;
  height: 3px;
  z-index: 200;
  pointer-events: none;
  background: transparent;
}
.st-progress__bar {
  display: block;
  height: 100%;
  width: 100%;
  background: var(--accent);
  transform: scaleX(0);
  transform-origin: 0 50%;
  will-change: transform;
}
body.st-no-progress .st-progress { display: none; }

/* ============================== UTILITY BAR ============================== */
.st-utility {
  background: var(--surface);
  border-bottom: var(--hairline);
  font-size: var(--fs-100);
  color: var(--muted);
}
.st-utility__in {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--sp-4);
  min-height: 38px;
}
.st-utility__left {
  display: flex;
  align-items: center;
  gap: 14px;
  min-width: 0;
}
.st-utility__date { white-space: nowrap; }
.st-utility__right {
  display: flex;
  align-items: center;
  gap: 16px;
  min-width: 0;
}

/* Text-size control (accessibility) */
.st-textsize {
  display: flex;
  align-items: center;
  gap: 4px;
}
.st-textsize__label {
  margin-right: 2px;
  font-weight: 600;
  color: var(--ink);
}
.st-textsize button {
  min-width: 30px;
  height: 26px;
  padding: 0 6px;
  border: 1px solid var(--border-strong);
  border-radius: 3px;
  background: var(--surface);
  color: var(--ink);
  font-size: .75rem;
  font-weight: 700;
  line-height: 1;
  transition: background .16s var(--ease), border-color .16s var(--ease);
}
.st-textsize button:hover {
  background: var(--primary-tint);
  border-color: var(--primary);
  color: var(--primary-dark);
}

/* Utility link list (native LinkList widget) */
#utility .widget,
#utility .widget-content { margin: 0; }
#utility h2 { display: none; }
#utility ul {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 14px;
  margin: 0;
  padding: 0;
  list-style: none;
}
#utility ul a {
  color: var(--muted);
  padding: 4px 0;
  display: inline-block;
}
#utility ul a:hover { color: var(--primary); }

@media (max-width: 719px) {
  .st-utility__date,
  .st-textsize__label { display: none; }
  .st-utility__in { justify-content: center; }
}

/* ============================== HEADER ============================== */
.st-header {
  background: var(--surface);
  border-bottom: var(--hairline);
}
.st-header__in {
  display: flex;
  align-items: center;
  gap: var(--sp-4);
  padding-block: 14px;
  min-height: 74px;
}
.st-brand { flex: 1 1 auto; min-width: 0; }

#header .widget { margin: 0; }
#header .header-widget,
#header .widget-content { margin: 0; }
#header h1,
#header .title {
  margin: 0;
  font-size: clamp(1.25rem, 1rem + 1.1vw, 1.75rem);
  font-weight: 800;
  letter-spacing: -.02em;
  line-height: 1.2;
}
#header h1 a,
#header .title a { color: var(--ink); }
#header h1 a:hover,
#header .title a:hover { color: var(--primary); }
#header p,
#header .description {
  margin: 2px 0 0;
  color: var(--muted);
  font-size: var(--fs-100);
  line-height: 1.4;
}
#header img { max-height: 56px; width: auto; }

/* Desktop inline search */
.st-searchform {
  display: none;
  flex: 0 1 330px;
  margin: 0;
}
@media (min-width: 900px) { .st-searchform { display: block; } }
.st-field {
  display: flex;
  align-items: stretch;
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-sm);
  background: var(--surface-2);
  overflow: hidden;
  transition: border-color .18s var(--ease), background .18s var(--ease);
}
.st-field:focus-within {
  border-color: var(--primary);
  background: var(--surface);
}
.st-field input[type="search"],
.st-field input[type="text"] {
  flex: 1 1 auto;
  min-width: 0;
  border: 0;
  background: transparent;
  padding: 9px 12px;
  font-size: var(--fs-200);
  -webkit-appearance: none;
  appearance: none;
}
.st-field input:focus { outline: none; }
.st-field input::-webkit-search-cancel-button { -webkit-appearance: none; }
.st-field button {
  flex: 0 0 auto;
  width: 42px;
  border: 0;
  border-left: 1px solid var(--border);
  background: var(--primary);
  color: #fff;
  display: grid;
  place-items: center;
  transition: background .18s var(--ease);
}
.st-field button:hover { background: var(--primary-dark); }

.st-header__actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: 0 0 auto;
}

.st-iconbtn {
  display: inline-grid;
  place-items: center;
  width: var(--tap);
  height: var(--tap);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--ink);
  transition: background .18s var(--ease), color .18s var(--ease),
    border-color .18s var(--ease);
}
.st-iconbtn:hover {
  background: var(--primary-tint);
  border-color: var(--primary);
  color: var(--primary-dark);
}
.st-iconbtn svg { width: 20px; height: 20px; }

@media (min-width: 900px) {
  .st-iconbtn--search { display: none; }
}
@media (max-width: 599px) {
  .st-header__in { min-height: 62px; padding-block: 10px; }
  .st-header .st-btn { display: none; }
}

/* ============================== PRIMARY NAV ============================== */
.st-nav {
  position: sticky;
  top: 0;
  z-index: 90;
  background: var(--nav-bg);
  color: var(--on-dark);
}
.st-nav__in {
  display: flex;
  align-items: stretch;
  justify-content: space-between;
  gap: var(--sp-3);
  min-height: var(--nav-h);
}

.st-navtoggle {
  display: none;
  align-items: center;
  gap: 9px;
  padding: 0 4px;
  border: 0;
  background: transparent;
  color: var(--on-dark);
  font-size: var(--fs-200);
  font-weight: 600;
}
.st-navtoggle svg { width: 22px; height: 22px; }

/* Drawer / nav panel — one DOM node, two presentations */
.st-drawer {
  display: flex;
  align-items: stretch;
  flex: 1 1 auto;
  min-width: 0;
}
.st-drawer__close {
  display: none;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  width: 100%;
  padding: 14px 4px;
  border: 0;
  border-bottom: var(--hairline);
  background: transparent;
  color: var(--ink);
  font-size: var(--fs-300);
  font-weight: 700;
  text-align: left;
}
.st-drawer__search { display: none; }

#navigation .widget,
#navigation .widget-content { margin: 0; }
#navigation h2 { display: none; }
#navigation ul {
  display: flex;
  align-items: stretch;
  flex-wrap: wrap;
  gap: 2px;
  margin: 0;
  padding: 0;
  list-style: none;
}
#navigation ul li { position: relative; margin: 0; }
#navigation ul a {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 0 15px;
  min-height: var(--nav-h);
  color: var(--on-dark);
  font-size: var(--fs-200);
  font-weight: 600;
  position: relative;
  transition: background .18s var(--ease), color .18s var(--ease);
}
#navigation ul a::after {
  content: "";
  position: absolute;
  left: 15px; right: 15px; bottom: 0;
  height: 3px;
  background: var(--accent);
  transform: scaleX(0);
  transform-origin: 0 50%;
  transition: transform .22s var(--ease);
}
#navigation ul a:hover,
#navigation ul a:focus-visible,
#navigation ul li.is-active > a {
  background: rgba(255, 255, 255, .09);
  color: #fff;
}
#navigation ul a:hover::after,
#navigation ul a:focus-visible::after,
#navigation ul li.is-active > a::after { transform: scaleX(1); }

/* Dropdown (see CUSTOMIZATION AREA (2) — submenu convention) */
#navigation .has-sub > a .st-caret {
  width: 12px; height: 12px;
  transition: transform .2s var(--ease);
}
#navigation .has-sub.is-open > a .st-caret { transform: rotate(180deg); }
#navigation ul ul {
  position: absolute;
  top: 100%;
  left: 0;
  z-index: 5;
  min-width: 226px;
  display: none;
  flex-direction: column;
  gap: 0;
  padding: 6px;
  background: var(--surface);
  border: var(--hairline);
  border-radius: var(--radius-sm);
  box-shadow: var(--shadow-3);
}
#navigation .has-sub.is-open > ul { display: flex; }
#navigation ul ul a {
  min-height: 40px;
  padding: 8px 12px;
  border-radius: 3px;
  color: var(--text);
  font-weight: 500;
  font-size: var(--fs-200);
}
#navigation ul ul a::after { display: none; }
#navigation ul ul a:hover,
#navigation ul ul a:focus-visible {
  background: var(--primary-tint);
  color: var(--primary-dark);
}

/* Right side of the nav strip */
.st-nav__side {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: 0 0 auto;
}
.st-nav__side .st-chip {
  background: rgba(255, 255, 255, .12);
  border-color: rgba(255, 255, 255, .2);
  color: var(--on-dark);
}
.st-nav__side .st-chip:hover {
  background: #fff;
  color: var(--primary-dark);
  border-color: #fff;
}
@media (max-width: 1099px) { .st-nav__side { display: none; } }

/* ---- Mobile drawer presentation ---- */
.st-scrim {
  position: fixed;
  inset: 0;
  z-index: 95;
  background: rgba(12, 26, 24, .5);
  opacity: 0;
  visibility: hidden;
  transition: opacity .25s var(--ease), visibility .25s var(--ease);
}
body.st-locked { overflow: hidden; }
body.st-locked .st-scrim { opacity: 1; visibility: visible; }

@media (max-width: 899px) {
  .st-navtoggle { display: flex; }
  .st-drawer {
    position: fixed;
    top: 0; bottom: 0; left: 0;
    z-index: 100;
    width: min(330px, 86vw);
    flex-direction: column;
    align-items: stretch;
    padding: 0 18px 24px;
    background: var(--surface);
    box-shadow: var(--shadow-3);
    overflow-y: auto;
    -webkit-overflow-scrolling: touch;
    transform: translateX(-101%);
    /* visibility keeps the closed drawer out of the tab order and out of
       the accessibility tree; the noscript block in <head> undoes it. */
    visibility: hidden;
    transition: transform .28s var(--ease), visibility .28s var(--ease);
  }
  body.st-drawer-open .st-drawer { transform: none; visibility: visible; }
  .st-drawer__close { display: flex; }
  .st-drawer__search {
    display: flex;
    align-items: center;
    gap: 10px;
    width: 100%;
    margin: 14px 0 6px;
    padding: 11px 14px;
    border: 1px solid var(--border-strong);
    border-radius: var(--radius-sm);
    background: var(--surface-2);
    color: var(--muted);
    font-size: var(--fs-200);
    text-align: left;
  }
  #navigation ul {
    flex-direction: column;
    align-items: stretch;
    gap: 0;
    padding-top: 6px;
  }
  #navigation ul a {
    min-height: 46px;
    padding: 10px 4px;
    color: var(--ink);
    border-bottom: var(--hairline);
    font-size: var(--fs-300);
  }
  #navigation ul a::after { display: none; }
  #navigation ul a:hover,
  #navigation ul li.is-active > a {
    background: transparent;
    color: var(--primary);
  }
  #navigation .has-sub > a .st-caret { margin-left: auto; }
  #navigation ul ul {
    position: static;
    display: none;
    min-width: 0;
    padding: 0 0 6px 12px;
    border: 0;
    border-left: 2px solid var(--primary-line);
    border-radius: 0;
    box-shadow: none;
    background: transparent;
  }
  #navigation .has-sub.is-open > ul { display: flex; }
  #navigation ul ul a {
    min-height: 40px;
    border-bottom: 0;
    color: var(--muted);
    font-size: var(--fs-200);
  }
  #navigation ul ul a:hover { color: var(--primary); }
}

/* ============================== ANNOUNCEMENT ==============================
   Optional strip. The theme ships it with an editable gadget; if you
   delete that gadget in Layout, the script collapses the whole strip. */
.st-announce {
  background: var(--primary-tint);
  border-bottom: 1px solid var(--primary-line);
  font-size: var(--fs-200);
}
#announcement .widget { margin: 0; }
#announcement .widget p { margin: 0; }
#announcement h2 { display: none; }
.st-announce__in {
  display: flex;
  align-items: center;
  gap: var(--sp-3);
  padding-block: 9px;
}
.st-announce__body { flex: 1 1 auto; min-width: 0; }
.st-announce__body strong { color: var(--primary-dark); }
.st-announce__body a { font-weight: 600; }
.st-announce__close {
  flex: 0 0 auto;
  width: 30px; height: 30px;
  display: grid;
  place-items: center;
  border: 1px solid var(--primary-line);
  border-radius: 3px;
  background: transparent;
  color: var(--primary-dark);
  line-height: 1;
}
.st-announce__close:hover { background: var(--surface); }
body.st-announce-off .st-announce { display: none; }

/* ============================== SEARCH OVERLAY ============================== */
.st-search-overlay {
  position: fixed;
  inset: 0;
  z-index: 150;
  display: grid;
  grid-template-rows: auto 1fr;
  background: rgba(12, 26, 24, .55);
  opacity: 0;
  visibility: hidden;
  transition: opacity .22s var(--ease), visibility .22s var(--ease);
}
body.st-search-open .st-search-overlay { opacity: 1; visibility: visible; }
.st-search-overlay__panel {
  background: var(--surface);
  border-bottom: 3px solid var(--accent);
  padding-block: clamp(20px, 5vw, 40px);
  transform: translateY(-14px);
  transition: transform .24s var(--ease);
}
body.st-search-open .st-search-overlay__panel { transform: none; }
.st-search-overlay__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--sp-4);
  margin-bottom: var(--sp-4);
}
.st-search-overlay__head h2 {
  margin: 0;
  font-size: var(--fs-400);
}
.st-search-overlay__head p {
  margin: 4px 0 0;
  color: var(--muted);
  font-size: var(--fs-100);
}
.st-search-overlay form { margin: 0; }
.st-search-overlay .st-field {
  border-width: 2px;
  border-color: var(--border-strong);
}
.st-search-overlay .st-field input { padding: 14px 16px; font-size: var(--fs-300); }
.st-search-overlay .st-field button { width: 56px; }
.st-search-overlay__hint {
  margin: 10px 0 0;
  color: var(--faint);
  font-size: var(--fs-100);
}
kbd {
  padding: 1px 6px;
  border: 1px solid var(--border-strong);
  border-bottom-width: 2px;
  border-radius: 3px;
  background: var(--surface-3);
  font-family: var(--font-mono);
  font-size: .8em;
}

/* ============================== HERO ============================== */
.st-hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 20px;
  padding-top: var(--sp-6);
}
@media (min-width: 960px) {
  .st-hero { grid-template-columns: minmax(0, 1.5fr) minmax(0, 1fr); gap: 24px; }
}

#hero,
#hero-aside {
  background: var(--surface);
  border: var(--hairline);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-1);
  overflow: hidden;
}

#hero .widget,
#hero .widget-content { margin: 0; }
#hero h2 { display: none; }
.st-intro {
  padding: clamp(22px, 4vw, 38px);
  border-top: 4px solid var(--primary);
  height: 100%;
}
.st-intro__title {
  font-size: var(--fs-600);
  margin-bottom: 12px;
  letter-spacing: -.02em;
}
.st-intro__text {
  color: var(--muted);
  font-size: var(--fs-300);
  max-width: 62ch;
}
.st-intro__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 20px;
}
.st-tiles {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 168px), 1fr));
  gap: 10px;
  margin: 24px 0 0;
  padding: 0;
  list-style: none;
}
.st-tiles a {
  display: block;
  padding: 12px 14px;
  border: var(--hairline);
  border-left: 3px solid var(--primary);
  border-radius: var(--radius-sm);
  background: var(--surface-2);
  color: var(--ink);
  font-weight: 600;
  font-size: var(--fs-200);
  transition: background .18s var(--ease), border-color .18s var(--ease),
    transform .18s var(--ease);
}
.st-tiles a:hover {
  background: var(--primary-tint);
  border-left-color: var(--accent);
  color: var(--primary-dark);
  transform: translateX(2px);
}

/* "Most read" panel — Blogger's own PopularPosts gadget, restyled as a
   ranked editorial list (CSS counters, so no markup changes are needed). */
#hero-aside .widget { margin: 0; }
#hero-aside h2 {
  margin: 0;
  padding: 20px clamp(16px, 3vw, 24px) 12px;
  border-bottom: var(--hairline);
  font-size: var(--fs-300);
}
#hero-aside .popular-posts ul {
  counter-reset: mr;
  margin: 0;
  padding: 8px clamp(16px, 3vw, 24px) 18px;
  list-style: none;
}
#hero-aside .popular-posts li {
  counter-increment: mr;
  display: flex;
  gap: 12px;
  padding: 10px 0;
  border-bottom: 1px dashed var(--border);
}
#hero-aside .popular-posts li:last-child { border-bottom: 0; padding-bottom: 0; }
#hero-aside .popular-posts li::before {
  content: counter(mr, decimal-leading-zero);
  flex: 0 0 auto;
  min-width: 22px;
  padding-top: 2px;
  color: var(--accent);
  font-size: .8125rem;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}
#hero-aside .item-title a {
  color: var(--ink);
  font-weight: 600;
  font-size: var(--fs-200);
  line-height: 1.42;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
#hero-aside .item-title a:hover { color: var(--primary); }
#hero-aside .item-thumbnail,
#hero-aside .item-snippet { display: none; }

/* ============================== PAGE HEAD (label / search / archive) ============================== */
.st-pagehead {
  background: var(--surface);
  border-bottom: var(--hairline);
  padding-block: var(--sp-5);
}
.st-pagehead__in { display: flex; flex-direction: column; gap: 6px; }
.st-pagehead h1 {
  margin: 0;
  font-size: var(--fs-500);
  letter-spacing: -.02em;
}
.st-pagehead p {
  margin: 0;
  color: var(--muted);
  font-size: var(--fs-200);
}
.st-crumbs {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 7px;
  margin: 0;
  padding: 0;
  list-style: none;
  color: var(--faint);
  font-size: var(--fs-100);
}
.st-crumbs a { color: var(--muted); }
.st-crumbs a:hover { color: var(--primary); }
.st-crumbs__sep { color: var(--border-strong); }
.st-crumbs [aria-current="page"] { color: var(--ink); font-weight: 600; }

/* ============================== FEED + CARDS ============================== */
.st-feed {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 292px), 1fr));
  gap: 20px;
}

.pcard {
  display: flex;
  flex-direction: column;
  background: var(--surface);
  border: var(--hairline);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-1);
  transition: transform .2s var(--ease), box-shadow .2s var(--ease),
    border-color .2s var(--ease);
}
.pcard:hover {
  transform: translateY(-3px);
  border-color: var(--primary-line);
  box-shadow: var(--shadow-2);
}

.pcard__media {
  display: block;
  position: relative;
  aspect-ratio: 16 / 9;
  background:
    repeating-linear-gradient(135deg, var(--surface-3) 0 10px, var(--surface-2) 10px 20px);
  overflow: hidden;
}
.pcard__media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform .45s var(--ease), opacity .3s var(--ease);
}
.pcard:hover .pcard__media img { transform: scale(1.035); }
.pcard__media.is-empty::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(135deg, var(--primary-tint), transparent 65%),
    repeating-linear-gradient(135deg, var(--surface-3) 0 12px, var(--surface-2) 12px 24px);
}

.pcard__body {
  display: flex;
  flex-direction: column;
  flex: 1 1 auto;
  gap: 9px;
  padding: 16px 18px 18px;
}
.pcard__cat { align-self: flex-start; }
.pcard__title {
  margin: 0;
  font-size: var(--fs-300);
  letter-spacing: -.012em;
}
.pcard__title a {
  color: var(--ink);
  display: -webkit-box;
  -webkit-line-clamp: 3;
  line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.pcard__title a:hover { color: var(--primary); }

/* Excerpt = the post body, clamped. JS strips images/scripts from it. */
.pcard__excerpt {
  color: var(--muted);
  font-size: var(--fs-200);
  line-height: 1.6;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.pcard__excerpt img,
.pcard__excerpt script,
.pcard__excerpt iframe,
.pcard__excerpt table,
.pcard__excerpt .separator { display: none !important; }

.pcard__foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: auto;
  padding-top: 12px;
  border-top: var(--hairline);
}
.pcard__more {
  font-size: var(--fs-100);
  font-weight: 700;
  letter-spacing: .04em;
  text-transform: uppercase;
  white-space: nowrap;
}
.pcard__more::after { content: " \2192"; }

/* ---- Lead / featured card ---- */
.pcard--lead {
  grid-column: 1 / -1;
  flex-direction: row;
  align-items: stretch;
}
.pcard--lead .pcard__media {
  flex: 0 0 46%;
  aspect-ratio: auto;
  min-height: 240px;
}
.pcard--lead .pcard__body { padding: clamp(20px, 3vw, 32px); gap: 12px; }
.pcard--lead .pcard__title { font-size: var(--fs-500); }
.pcard--lead .pcard__title a { -webkit-line-clamp: 3; line-clamp: 3; }
.pcard--lead .pcard__excerpt { -webkit-line-clamp: 4; line-clamp: 4; font-size: var(--fs-200); }
@media (max-width: 719px) {
  .pcard--lead { flex-direction: column; }
  .pcard--lead .pcard__media { flex: 0 0 auto; aspect-ratio: 16 / 9; min-height: 0; }
}

/* ---- Compact list card (JS-built rails) ---- */
.xcard {
  display: flex;
  gap: 12px;
  padding: 12px 0;
  border-bottom: 1px dashed var(--border);
}
.xcard:last-child { border-bottom: 0; padding-bottom: 0; }
.xcard__media {
  flex: 0 0 84px;
  width: 84px;
  aspect-ratio: 4 / 3;
  border-radius: var(--radius-sm);
  overflow: hidden;
  background: var(--surface-3);
}
.xcard__media img { width: 100%; height: 100%; object-fit: cover; }
.xcard__title {
  margin: 0 0 4px;
  font-size: var(--fs-200);
  font-weight: 600;
  line-height: 1.4;
}
.xcard__title a {
  color: var(--ink);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.xcard__title a:hover { color: var(--primary); }

/* ---- Horizontal card (related posts) ---- */
.hcard {
  display: flex;
  gap: 14px;
  padding: 14px;
  background: var(--surface);
  border: var(--hairline);
  border-radius: var(--radius-md);
  transition: border-color .2s var(--ease), box-shadow .2s var(--ease);
}
.hcard:hover { border-color: var(--primary-line); box-shadow: var(--shadow-2); }
.hcard__media {
  flex: 0 0 116px;
  width: 116px;
  aspect-ratio: 4 / 3;
  border-radius: var(--radius-sm);
  overflow: hidden;
  background: var(--surface-3);
}
.hcard__media img { width: 100%; height: 100%; object-fit: cover; }
.hcard__title { margin: 0 0 6px; font-size: var(--fs-200); font-weight: 600; }
.hcard__title a { color: var(--ink); }
.hcard__title a:hover { color: var(--primary); }

.st-rail {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 300px), 1fr));
  gap: 14px;
}
.st-rail--compact {
  gap: 0 28px;
  padding: 6px 18px;
  background: var(--surface);
  border: var(--hairline);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-1);
}

/* Sections built from the same-origin Blogger feed (see JS notes) */
.st-feed-section { margin-top: var(--sp-7); }
.st-feed-section[hidden] { display: none; }

/* ============================== ARTICLE ============================== */
.st-article { background: transparent; }
.st-article__head { margin-bottom: var(--sp-5); }
.st-article__cat { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 12px; }
.st-article__title {
  font-size: var(--fs-600);
  margin: 0 0 14px;
  letter-spacing: -.022em;
}
.st-article__meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 14px;
  padding-bottom: 16px;
  border-bottom: var(--hairline);
}
.st-avatar {
  width: 34px; height: 34px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: var(--primary-tint);
  color: var(--primary-dark);
  font-weight: 700;
  font-size: .8125rem;
}
.st-article__media {
  margin: 0 0 var(--sp-5);
  border-radius: var(--radius-md);
  overflow: hidden;
  border: var(--hairline);
  background: var(--surface-3);
}
.st-article__media img { width: 100%; height: auto; }
.st-article__media figcaption {
  padding: 8px 12px;
  background: var(--surface);
  color: var(--muted);
  font-size: var(--fs-100);
  border-top: var(--hairline);
}

/* Table of contents (generated by JS) */
.st-toc {
  margin: 0 0 var(--sp-5);
  padding: 14px 18px;
  border: 1px solid var(--primary-line);
  border-left: 3px solid var(--primary);
  border-radius: var(--radius-sm);
  background: var(--surface);
  font-size: var(--fs-200);
}
.st-toc summary {
  cursor: pointer;
  font-weight: 700;
  color: var(--ink);
  list-style: none;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}
.st-toc summary::-webkit-details-marker { display: none; }
.st-toc summary::after {
  content: "+";
  color: var(--primary);
  font-size: 1.1em;
  font-weight: 700;
}
.st-toc[open] summary::after { content: "\2212"; }
.st-toc ol {
  counter-reset: toc;
  margin: 12px 0 0;
  padding: 0;
  list-style: none;
  border-top: var(--hairline);
  padding-top: 10px;
}
.st-toc ol ol { border-top: 0; padding-top: 0; margin: 2px 0 0 14px; }
.st-toc li { counter-increment: toc; margin: 3px 0; }
.st-toc a {
  display: block;
  padding: 3px 0;
  color: var(--text);
  border-left: 2px solid transparent;
  padding-left: 8px;
  margin-left: -10px;
}
.st-toc a:hover { color: var(--primary); border-left-color: var(--primary-line); }
.st-toc a.is-current {
  color: var(--primary-dark);
  font-weight: 600;
  border-left-color: var(--accent);
}

/* Long-form typography */
.post-body {
  max-width: 74ch;
  color: var(--text);
  font-size: var(--fs-300);
  line-height: 1.8;
}
.post-body > *:first-child { margin-top: 0; }
.post-body p { margin: 0 0 1.25em; }
.post-body h2,
.post-body h3,
.post-body h4 {
  scroll-margin-top: calc(var(--nav-h) + 20px);
  margin: 1.9em 0 .6em;
  line-height: 1.32;
}
.post-body h2 {
  font-size: var(--fs-500);
  padding-left: 14px;
  border-left: 4px solid var(--accent);
}
.post-body h3 { font-size: var(--fs-400); }
.post-body h4 { font-size: var(--fs-300); }
.post-body a {
  color: var(--primary);
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
  text-decoration-color: var(--primary-line);
}
.post-body a:hover {
  color: var(--accent);
  text-decoration-color: var(--accent);
}
.post-body ul,
.post-body ol { margin: 0 0 1.25em; padding-left: 1.4em; }
.post-body li { margin-bottom: .4em; }
.post-body li::marker { color: var(--primary); }
.post-body strong { color: var(--ink); font-weight: 700; }
.post-body img {
  border-radius: var(--radius-sm);
  margin-inline: auto;
}
.post-body .separator { text-align: center; margin: 1.5em 0; }
.post-body .separator a { display: inline-block; }
.post-body blockquote {
  margin: 1.6em 0;
  padding: 4px 0 4px 20px;
  border-left: 4px solid var(--primary);
  color: var(--ink);
  font-size: 1.06em;
  font-style: italic;
}
.post-body blockquote p:last-child { margin-bottom: 0; }
.post-body pre {
  position: relative;
  margin: 1.5em 0;
  padding: 16px;
  border: var(--hairline);
  border-radius: var(--radius-sm);
  background: var(--surface-2);
  overflow-x: auto;
  font-family: var(--font-mono);
  font-size: .875em;
  line-height: 1.6;
}
.post-body code {
  padding: .1em .35em;
  border-radius: 3px;
  background: var(--surface-3);
  font-family: var(--font-mono);
  font-size: .875em;
}
.post-body pre code { padding: 0; background: transparent; }
.st-copybtn {
  position: absolute;
  top: 8px; right: 8px;
  padding: 4px 9px;
  border: 1px solid var(--border-strong);
  border-radius: 3px;
  background: var(--surface);
  color: var(--muted);
  font-size: .75rem;
  font-weight: 600;
}
.st-copybtn:hover { border-color: var(--primary); color: var(--primary-dark); }
.st-tablewrap {
  margin: 1.5em 0;
  overflow-x: auto;
  border: var(--hairline);
  border-radius: var(--radius-sm);
  -webkit-overflow-scrolling: touch;
}
.post-body table {
  margin: 0;
  font-size: .92em;
  min-width: 480px;
}
.post-body th,
.post-body td {
  padding: 10px 12px;
  border-bottom: 1px solid var(--border);
  text-align: left;
}
.post-body thead th {
  background: var(--surface-3);
  color: var(--ink);
  font-weight: 700;
  white-space: nowrap;
}
.post-body tbody tr:hover { background: var(--surface-2); }
.post-body hr { margin: 2em 0; }

/* Labels under the article */
.st-labels {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin: var(--sp-5) 0;
  padding-top: var(--sp-4);
  border-top: var(--hairline);
}
.st-labels__label {
  color: var(--muted);
  font-size: var(--fs-100);
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
}

/* Share bar */
.st-share {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  padding: 14px 16px;
  background: var(--surface);
  border: var(--hairline);
  border-radius: var(--radius-md);
  margin-bottom: var(--sp-5);
}
.st-share__label {
  font-size: var(--fs-100);
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--muted);
  margin-right: 2px;
}
.st-share__btn {
  display: inline-grid;
  place-items: center;
  width: 40px; height: 40px;
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--muted);
  transition: background .18s var(--ease), color .18s var(--ease),
    border-color .18s var(--ease), transform .12s var(--ease);
}
.st-share__btn svg { width: 18px; height: 18px; }
.st-share__btn:hover { transform: translateY(-2px); color: #fff; }
.st-share__btn--wa:hover { background: #128c4b; border-color: #128c4b; }
.st-share__btn--fb:hover { background: #1877f2; border-color: #1877f2; }
.st-share__btn--x:hover { background: #10151b; border-color: #10151b; }
.st-share__btn--tg:hover { background: #1d88c9; border-color: #1d88c9; }
.st-share__btn--in:hover { background: #0a66c2; border-color: #0a66c2; }
.st-share__btn--copy:hover { background: var(--primary); border-color: var(--primary); }

/* Author box */
.st-author {
  display: flex;
  gap: 16px;
  padding: 20px;
  background: var(--surface);
  border: var(--hairline);
  border-radius: var(--radius-md);
  margin-bottom: var(--sp-5);
}
.st-author__avatar {
  flex: 0 0 56px;
  width: 56px; height: 56px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: var(--primary);
  color: #fff;
  font-size: 1.25rem;
  font-weight: 700;
}
.st-author__name { margin: 0 0 4px; font-size: var(--fs-300); }
.st-author__role {
  margin: 0 0 8px;
  color: var(--faint);
  font-size: var(--fs-100);
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
}
.st-author__bio { color: var(--muted); font-size: var(--fs-200); }

/* Post pagination (newer / older) */
.st-postnav {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 12px;
  margin-bottom: var(--sp-5);
}
@media (min-width: 640px) { .st-postnav { grid-template-columns: 1fr 1fr; } }
.st-postnav a {
  display: block;
  padding: 14px 16px;
  border: var(--hairline);
  border-radius: var(--radius-md);
  background: var(--surface);
  transition: border-color .18s var(--ease), background .18s var(--ease);
}
.st-postnav a:hover { border-color: var(--primary); background: var(--primary-tint); }
.st-postnav__dir {
  display: block;
  color: var(--faint);
  font-size: .6875rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  margin-bottom: 4px;
}
.st-postnav__title {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  color: var(--ink);
  font-weight: 600;
  font-size: var(--fs-200);
}
.st-postnav a:hover .st-postnav__title { color: var(--primary-dark); }
.st-postnav .st-postnav--next { text-align: right; }

/* Index pagination */
.st-pager {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 10px;
  margin-top: var(--sp-6);
  padding-top: var(--sp-5);
  border-top: var(--hairline);
}
.st-pager a {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 40px;
  padding: 8px 18px;
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--ink);
  font-weight: 600;
  font-size: var(--fs-200);
  transition: background .18s var(--ease), border-color .18s var(--ease);
}
.st-pager a:hover {
  background: var(--primary);
  border-color: var(--primary);
  color: #fff;
}

/* Comments */
.st-comments {
  margin-top: var(--sp-6);
  padding-top: var(--sp-5);
  border-top: var(--hairline);
}
.st-comments__title { font-size: var(--fs-400); margin-bottom: var(--sp-4); }
.st-comment {
  display: flex;
  gap: 12px;
  padding: 14px 0;
  border-bottom: 1px dashed var(--border);
}
.st-comment:last-of-type { border-bottom: 0; }
.st-comment__avatar {
  flex: 0 0 38px;
  width: 38px; height: 38px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: var(--surface-3);
  color: var(--muted);
  font-weight: 700;
  font-size: .8125rem;
}
.st-comment__head {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 8px;
  margin-bottom: 4px;
}
.st-comment__author { color: var(--ink); font-weight: 700; font-size: var(--fs-200); }
.st-comment__date { color: var(--faint); font-size: var(--fs-100); }
.st-comment__body { color: var(--text); font-size: var(--fs-200); }
.st-comment__body p { margin: 0 0 .6em; }
.st-comment__delete { font-size: var(--fs-100); }
.st-comments__cta { margin-top: var(--sp-4); }

/* Static page */
.st-page {
  background: var(--surface);
  border: var(--hairline);
  border-radius: var(--radius-md);
  padding: clamp(20px, 4vw, 40px);
}
.st-page__title { font-size: var(--fs-600); margin-bottom: 16px; }
.st-page .post-body { max-width: 78ch; }

/* ============================== SIDEBAR ============================== */
.st-sidebar { display: grid; gap: 20px; align-content: start; }
/* Opt-in: add the class "st-sticky-sidebar" to <body> in the template to pin
   the sidebar. Off by default because a sidebar taller than the viewport
   would keep its lower gadgets out of reach while stuck. */
body.st-sticky-sidebar .st-sidebar {
  position: sticky;
  top: calc(var(--nav-h) + 20px);
}

.st-sidebar .widget,
.st-box {
  background: var(--surface);
  border: var(--hairline);
  border-radius: var(--radius-md);
  padding: 18px;
  box-shadow: var(--shadow-1);
  margin: 0 0 0;
}
.st-sidebar .widget h2,
.st-box h2 {
  margin: 0 0 14px;
  padding-bottom: 10px;
  border-bottom: var(--hairline);
  font-size: var(--fs-300);
  letter-spacing: -.01em;
}
.st-sidebar .widget-content { margin: 0; }
.st-sidebar ul { margin: 0; padding: 0; list-style: none; }

/* Sidebar search widget (native BlogSearch) */
#BlogSearch1 form { margin: 0; }
#BlogSearch1 .search-input,
#BlogSearch1 input[type="text"] {
  width: 100%;
  padding: 10px 12px;
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-sm);
  background: var(--surface-2);
  margin-bottom: 8px;
}
#BlogSearch1 .search-action,
#BlogSearch1 input[type="submit"] {
  width: 100%;
  min-height: 40px;
  border: 0;
  border-radius: var(--radius-sm);
  background: var(--primary);
  color: #fff;
  font-weight: 600;
}
#BlogSearch1 .search-action:hover,
#BlogSearch1 input[type="submit"]:hover { background: var(--primary-dark); }

/* Popular posts in sidebar — compact list */
.st-sidebar .popular-posts ul { counter-reset: pp; }
.st-sidebar .popular-posts li {
  counter-increment: pp;
  display: flex;
  gap: 12px;
  padding: 11px 0;
  border-bottom: 1px dashed var(--border);
}
.st-sidebar .popular-posts li:last-child { border-bottom: 0; padding-bottom: 0; }
.st-sidebar .popular-posts .item-thumbnail {
  flex: 0 0 72px;
  width: 72px;
  aspect-ratio: 4 / 3;
  border-radius: var(--radius-sm);
  overflow: hidden;
  background: var(--surface-3);
}
.st-sidebar .popular-posts .item-thumbnail img {
  width: 100%; height: 100%; object-fit: cover;
}
.st-sidebar .popular-posts .item-title a {
  color: var(--ink);
  font-weight: 600;
  font-size: var(--fs-200);
  line-height: 1.42;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.st-sidebar .popular-posts .item-title a:hover { color: var(--primary); }
.st-sidebar .popular-posts .item-snippet {
  color: var(--muted);
  font-size: var(--fs-100);
  margin-top: 3px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* Labels widget */
.st-sidebar .list-label-widget-content li,
.st-sidebar .cloud-label-widget-content li {
  display: inline-block;
  margin: 0 6px 6px 0;
}
.st-sidebar .list-label-widget-content a,
.st-sidebar .cloud-label-widget-content a,
.st-sidebar .label-size {
  display: inline-block;
  padding: 5px 11px;
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-pill);
  background: var(--surface-2);
  color: var(--text);
  font-size: var(--fs-100);
  transition: background .16s var(--ease), color .16s var(--ease),
    border-color .16s var(--ease);
}
.st-sidebar .list-label-widget-content a:hover,
.st-sidebar .cloud-label-widget-content a:hover,
.st-sidebar .label-size:hover {
  background: var(--primary);
  border-color: var(--primary);
  color: #fff;
}
.st-sidebar .label-count {
  color: var(--faint);
  font-size: .75rem;
  margin-left: 4px;
}

/* Archive widget */
#BlogArchive1 select {
  width: 100%;
  padding: 10px 12px;
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-sm);
  background: var(--surface-2);
}
#BlogArchive1 ul { margin: 0; padding: 0; list-style: none; }
#BlogArchive1 li { border-bottom: 1px dashed var(--border); }
#BlogArchive1 li:last-child { border-bottom: 0; }
#BlogArchive1 li a {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  padding: 9px 0;
  color: var(--text);
  font-size: var(--fs-200);
}
#BlogArchive1 li a:hover { color: var(--primary); }
#BlogArchive1 .post-count { color: var(--faint); font-size: var(--fs-100); }

/* Sidebar HTML widget content */
.st-sidebar .widget.HTML .widget-content { font-size: var(--fs-200); color: var(--muted); }
.st-sidebar .widget.HTML .widget-content p { margin: 0 0 10px; }
.st-follow {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 12px;
}

/* ============================== ADS ============================== */
/* Empty ad sections render nothing at all: no padding and no min-height
   on the section itself, so an unfilled slot cannot shift the layout.
   All the chrome lives on the gadget inside it. */
.st-ad .widget {
  margin: 0;
  padding: 14px;
  background: var(--surface);
  border: var(--hairline);
  border-radius: var(--radius-md);
  text-align: center;
}
.st-ad .widget h2 { display: none; }
.st-ad .widget + .widget { margin-top: 16px; }
.st-ad--header .widget { margin-top: var(--sp-4); }
.st-ad--mid .widget,
.st-ad--footer .widget { margin-block: var(--sp-5) 0; }
.st-ad--article .widget { margin-top: var(--sp-4); }
.st-ad--end .widget { margin-top: var(--sp-5); }
.st-ad--sidebar .widget { margin-bottom: 0; }
body.st-no-ads .st-ad { display: none; }
.post-body ins { display: block; margin: 1.5em 0; text-align: center; }

/* ============================== NEWSLETTER ============================== */
.st-subscribe {
  background: var(--surface);
  border-top: var(--hairline);
  border-bottom: var(--hairline);
  padding-block: var(--sp-7);
}
.st-subscribe__in {
  max-width: 720px;
  margin-inline: auto;
  text-align: center;
}
.st-subscribe h2 { font-size: var(--fs-500); margin-bottom: 10px; }
.st-subscribe p { color: var(--muted); font-size: var(--fs-300); }
.st-subscribe__actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 10px;
  margin-top: 20px;
}
#newsletter { margin: 0; }
#newsletter .widget {
  max-width: 460px;
  margin: 20px auto 0;
  text-align: left;
}
#newsletter h2 { display: none; }
#newsletter input[type="email"],
#newsletter input[type="text"] {
  width: 100%;
  padding: 11px 13px;
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-sm);
  background: var(--surface-2);
  margin-bottom: 8px;
}
#newsletter input[type="submit"],
#newsletter button {
  width: 100%;
  min-height: var(--tap);
  border: 0;
  border-radius: var(--radius-sm);
  background: var(--primary);
  color: #fff;
  font-weight: 600;
}

/* ============================== FOOTER ============================== */
.st-footer {
  background: var(--footer-bg);
  color: var(--on-dark);
  padding-top: var(--sp-7);
}
.st-footer a { color: var(--on-dark-muted); }
.st-footer a:hover { color: #fff; }
.st-footer h2,
.st-footer h3 { color: #fff; }
.st-footer__grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: var(--sp-6);
  padding-bottom: var(--sp-6);
}
@media (min-width: 640px) { .st-footer__grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (min-width: 1024px) { .st-footer__grid { grid-template-columns: 1.4fr 1fr 1fr 1.2fr; gap: 40px; } }

.st-footer .widget { margin: 0; }
.st-footer .widget h2 {
  margin: 0 0 14px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--footer-line);
  font-size: var(--fs-200);
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
}
.st-footer .widget-content { font-size: var(--fs-200); color: var(--on-dark-muted); }
.st-footer ul { margin: 0; padding: 0; list-style: none; }
.st-footer li { margin-bottom: 8px; }
.st-footer li a {
  display: inline-block;
  padding: 2px 0;
  font-size: var(--fs-200);
}
.st-footer .label-count,
.st-footer .post-count { color: rgba(255, 255, 255, .45); font-size: .75rem; }
.st-footer__about p { margin: 0 0 12px; }

.st-social {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 14px;
}
.st-social a {
  display: inline-grid;
  place-items: center;
  width: 38px; height: 38px;
  border: 1px solid var(--footer-line);
  border-radius: var(--radius-sm);
  color: var(--on-dark-muted);
  transition: background .18s var(--ease), color .18s var(--ease),
    border-color .18s var(--ease);
}
.st-social a:hover { background: #fff; color: var(--primary-dark); border-color: #fff; }
.st-social svg { width: 17px; height: 17px; }

.st-footer__contact li {
  display: flex;
  gap: 9px;
  align-items: flex-start;
  margin-bottom: 10px;
}
.st-footer__contact svg {
  flex: 0 0 auto;
  width: 16px; height: 16px;
  margin-top: 3px;
  opacity: .8;
}

.st-footer__bottom {
  border-top: 1px solid var(--footer-line);
  padding-block: 16px;
  background: rgba(0, 0, 0, .12);
}
.st-footer__bottom-in {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 10px 20px;
  font-size: var(--fs-100);
  color: var(--on-dark-muted);
}
#footer-bottom .widget { margin: 0; }
#footer-bottom .widget-content { font-size: var(--fs-100); }
#footer-bottom .copyright { color: var(--on-dark-muted); }
#footer-bottom .copyright a { color: var(--on-dark-muted); }
.st-footer__note { margin: 0; }

/* ============================== 404 + EMPTY STATES ============================== */
.st-404 {
  display: grid;
  gap: 24px;
  align-items: center;
  padding-block: var(--sp-7);
}
@media (min-width: 760px) { .st-404 { grid-template-columns: minmax(0, 300px) minmax(0, 1fr); gap: 40px; } }
.st-404__art {
  display: grid;
  place-items: center;
  padding: 20px;
  border: var(--hairline);
  border-radius: var(--radius-lg);
  background: var(--surface);
}
.st-404__code {
  margin: 0 0 8px;
  font-size: clamp(3rem, 2rem + 6vw, 5rem);
  font-weight: 800;
  line-height: 1;
  color: var(--primary);
  letter-spacing: -.03em;
}
.st-404 h1 { font-size: var(--fs-500); margin-bottom: 10px; }
.st-404__text { color: var(--muted); font-size: var(--fs-300); max-width: 60ch; }
.st-404__actions { display: flex; flex-wrap: wrap; gap: 10px; margin: 20px 0; }
.st-404 form { max-width: 480px; }
.st-404__links {
  margin: 20px 0 0;
  padding: 0;
  list-style: none;
  display: grid;
  gap: 6px;
}
.st-404__links a { font-weight: 600; }
.st-404__links a::before { content: "\2192\00a0\00a0"; color: var(--accent); }

/* Blogger status messages (no results / notices) */
.status-msg-wrap {
  margin: 0 0 var(--sp-5);
  padding: 14px 16px;
  border: 1px solid var(--border-strong);
  border-left: 3px solid var(--accent);
  border-radius: var(--radius-sm);
  background: var(--surface);
  font-size: var(--fs-200);
}
.status-msg-body { color: var(--muted); }
.status-msg-body a { font-weight: 600; }
.status-msg-border,
.status-msg-bg,
.status-msg-hidden { display: none; }

.st-empty {
  padding: var(--sp-7) var(--sp-5);
  border: 1px dashed var(--border-strong);
  border-radius: var(--radius-md);
  background: var(--surface);
  text-align: center;
}
.st-empty h2 { font-size: var(--fs-400); margin-bottom: 8px; }
.st-empty p { color: var(--muted); max-width: 52ch; margin-inline: auto; }

/* ============================== BACK TO TOP ============================== */
.st-totop {
  position: fixed;
  right: 18px;
  bottom: 18px;
  z-index: 80;
  width: 46px; height: 46px;
  display: grid;
  place-items: center;
  border: 0;
  border-radius: var(--radius-pill);
  background: var(--primary);
  color: #fff;
  box-shadow: var(--shadow-2);
  opacity: 0;
  visibility: hidden;
  transform: translateY(12px);
  transition: opacity .22s var(--ease), transform .22s var(--ease),
    visibility .22s var(--ease), background .18s var(--ease);
}
.st-totop.is-visible { opacity: 1; visibility: visible; transform: none; }
.st-totop:hover { background: var(--primary-dark); }
.st-totop svg { width: 20px; height: 20px; }
@media (max-width: 599px) { .st-totop { right: 12px; bottom: 12px; } }

/* Blogger chrome we do not want */
#navbar-iframe,
.navbar { display: none !important; height: 0; }
.blog-feeds,
.post-feeds,
.feed-links { display: none; }
.post-icons,
.reactions { display: none; }

/* ============================== REDUCED MOTION ============================== */
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *,
  *::before,
  *::after {
    animation-duration: .001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .001ms !important;
    scroll-behavior: auto !important;
  }
  .pcard:hover { transform: none; }
  .st-totop { transform: none; }
  .st-progress { display: none; }
}

/* ============================== PRINT ============================== */
@media print {
  .st-utility,
  .st-nav,
  .st-header__actions,
  .st-searchform,
  .st-sidebar,
  .st-share,
  .st-totop,
  .st-progress,
  .st-ad,
  .st-subscribe,
  .st-footer,
  .st-pager,
  .st-comments,
  .st-toc { display: none !important; }
  body { background: #fff; color: #000; font-size: 12pt; }
  .st-grid { grid-template-columns: minmax(0, 1fr); }
  .post-body { max-width: none; font-size: 11.5pt; }
  .post-body a { color: #000; text-decoration: underline; }
  .post-body a::after { content: " (" attr(href) ")"; font-size: .85em; }
  a { color: #000; }
}

body.script:
//
/* ==================================================================
   SAARTHI — theme behaviour
   Vanilla JS. No jQuery, no libraries, no globals, no tracking.
   Every feature degrades: with JS disabled the site still reads,
   navigates and searches (all search forms are real Blogger forms).
   ================================================================== */
(function (window, document) {
  'use strict';

  /* >>> CUSTOMIZATION AREA (3 of 3) — THEME BEHAVIOUR <<<
     Change these values, or toggle features, then re-upload. */
  var CFG = {
    /* Label used by the optional homepage "Featured" section.
       Posts without this label simply do not appear there. */
    featuredLabel: 'Featured',
    featuredCount: 4,
    /* Related posts are pulled from the first label of the article
       through Blogger's own feed (same origin, no third party). */
    relatedCount: 5,
    /* Turn a whole feature off without touching any other code. */
    enableFeatured: true,
    enableRelated: true,
    enableProgress: true,
    enableToc: true,
    minTocHeadings: 3,
    readingWpm: 180
  };

  var root = document.documentElement;
  var body = document.body;
  var pageType = body.getAttribute('data-pagetype') || '';
  var isItem = pageType === 'item';
  var reduced = false;
  var mqReduce = window.matchMedia ? window.matchMedia('(prefers-reduced-motion: reduce)') : null;
  if (mqReduce) { reduced = mqReduce.matches; }
  var mqDesktop = window.matchMedia ? window.matchMedia('(min-width: 900px)') : null;

  function $(sel, ctx) { return (ctx || document).querySelector(sel); }
  function $$(sel, ctx) {
    var out = [];
    var list = (ctx || document).querySelectorAll(sel);
    for (var i = 0; i < list.length; i++) { out.push(list[i]); }
    return out;
  }
  function on(el, ev, fn, opts) { if (el) { el.addEventListener(ev, fn, opts || false); } }
  function storageGet(k) { try { return window.localStorage.getItem(k); } catch (e) { return null; } }
  function storageSet(k, v) { try { window.localStorage.setItem(k, v); } catch (e) { /* private mode */ } }

  /* ---------------------------------------------------------------
     1. Accessibility: text size
     --------------------------------------------------------------- */
  (function textControls() {
    var steps = [90, 100, 112, 125];
    var idx = 1;
    var saved = parseFloat(storageGet('st-fs'));
    if (steps.indexOf(saved) > -1) { idx = steps.indexOf(saved); }
    function apply() {
      root.style.fontSize = steps[idx] + '%';
      storageSet('st-fs', String(steps[idx]));
      var dec = $('#st-fs-dec'), inc = $('#st-fs-inc');
      if (dec) { dec.disabled = idx === 0; }
      if (inc) { inc.disabled = idx === steps.length - 1; }
    }
    on($('#st-fs-dec'), 'click', function () { if (idx > 0) { idx--; apply(); } });
    on($('#st-fs-inc'), 'click', function () { if (idx < steps.length - 1) { idx++; apply(); } });
    on($('#st-fs-reset'), 'click', function () { idx = 1; apply(); });
    apply();
  }());

  /* ---------------------------------------------------------------
     2. Mobile navigation drawer
     --------------------------------------------------------------- */
  (function drawer() {
    var toggle = $('#st-navtoggle');
    var panel = $('#st-drawer');
    var scrim = $('#st-scrim');
    var close = $('#st-drawer-close');
    if (!toggle || !panel) { return; }
    var lastFocus = null;

    function focusables() {
      return $$('a[href], button:not([disabled])', panel).filter(function (el) {
        return el.offsetParent !== null;
      });
    }
    function open() {
      lastFocus = document.activeElement;
      body.classList.add('st-locked', 'st-drawer-open');
      toggle.setAttribute('aria-expanded', 'true');
      toggle.setAttribute('aria-label', 'Close menu');
      panel.setAttribute('aria-hidden', 'false');
      var f = focusables();
      if (f.length) { f[0].focus(); }
    }
    function closeDrawer() {
      body.classList.remove('st-locked', 'st-drawer-open');
      toggle.setAttribute('aria-expanded', 'false');
      toggle.setAttribute('aria-label', 'Open menu');
      if (mqDesktop && mqDesktop.matches) { panel.removeAttribute('aria-hidden'); }
      else { panel.setAttribute('aria-hidden', 'true'); }
      if (lastFocus && lastFocus.focus) { lastFocus.focus(); }
    }
    on(toggle, 'click', function () {
      if (body.classList.contains('st-drawer-open')) { closeDrawer(); } else { open(); }
    });
    on(close, 'click', closeDrawer);
    on(scrim, 'click', closeDrawer);
    on(document, 'keydown', function (e) {
      if (!body.classList.contains('st-drawer-open')) { return; }
      if (e.key === 'Escape' || e.key === 'Esc') { closeDrawer(); return; }
      if (e.key !== 'Tab') { return; }
      var f = focusables();
      if (!f.length) { return; }
      var first = f[0], last = f[f.length - 1];
      if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
      else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
    });
    /* Close the drawer if the viewport grows past the mobile breakpoint */
    if (mqDesktop && mqDesktop.addEventListener) {
      mqDesktop.addEventListener('change', function (e) {
        if (e.matches && body.classList.contains('st-drawer-open')) { closeDrawer(); }
      });
    }
  }());

  /* ---------------------------------------------------------------
     3. Primary menu: submenus, active state
        Submenu convention: in Layout -> Main Menu, prefix a link's
        TEXT with "- " to nest it under the previous top-level link.
     --------------------------------------------------------------- */
  (function menu() {
    var nav = $('#navigation ul');
    if (!nav) { return; }
    var items = $$(':scope > li', nav);
    var i, li, a, text;

    /* Build submenus from the "- " text convention */
    var pending = null;
    for (i = 0; i < items.length; i++) {
      li = items[i];
      a = $('a', li);
      if (!a) { continue; }
      text = (a.textContent || '').replace(/^\s+/, '');
      if (text.indexOf('- ') === 0 || text.indexOf('\u2013 ') === 0) {
        if (pending) {
          a.textContent = text.replace(/^[-\u2013]\s+/, '');
          var sub = $('ul', pending) || document.createElement('ul');
          if (!sub.parentNode) { pending.appendChild(sub); }
          var wrap = document.createElement('li');
          wrap.appendChild(a.parentNode.removeChild(a));
          sub.appendChild(wrap);
          li.parentNode.removeChild(li);
        }
      } else {
        pending = li;
      }
    }

    /* Caret + a11y wiring for every parent that now has children */
    var parents = $$('#navigation ul > li').filter(function (el) { return !!$('ul', el); });
    parents.forEach(function (p) {
      p.classList.add('has-sub');
      var link = $(':scope > a', p);
      if (!link) { return; }
      link.setAttribute('aria-haspopup', 'true');
      link.setAttribute('aria-expanded', 'false');
      var caret = document.createElement('span');
      caret.className = 'st-caret';
      caret.setAttribute('aria-hidden', 'true');
      caret.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" ' +
        'stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M6 9l6 6 6-6"/></svg>';
      link.appendChild(caret);

      function setOpen(state) {
        p.classList.toggle('is-open', state);
        link.setAttribute('aria-expanded', state ? 'true' : 'false');
      }
      on(link, 'click', function (e) {
        /* On touch/mobile the parent only expands; on wide screens the
           parent link still works as a real destination. */
        var narrow = !(mqDesktop && mqDesktop.matches);
        if (narrow) { e.preventDefault(); setOpen(!p.classList.contains('is-open')); }
      });
      on(p, 'mouseenter', function () { if (mqDesktop && mqDesktop.matches) { setOpen(true); } });
      on(p, 'mouseleave', function () { if (mqDesktop && mqDesktop.matches) { setOpen(false); } });
      on(link, 'focus', function () { setOpen(true); });
      on(p, 'focusout', function (e) {
        if (!p.contains(e.relatedTarget)) { setOpen(false); }
      });
    });

    on(document, 'keydown', function (e) {
      if (e.key !== 'Escape' && e.key !== 'Esc') { return; }
      parents.forEach(function (p) {
        p.classList.remove('is-open');
        var l = $(':scope > a', p);
        if (l) { l.setAttribute('aria-expanded', 'false'); }
      });
    });

    /* Mark the current section */
    var here = (window.location.pathname || '/').replace(/\/+$/, '') || '/';
    $$('#navigation a[href]').forEach(function (link) {
      try {
        var u = new URL(link.getAttribute('href'), window.location.href);
        if (u.host !== window.location.host) { return; }
        var path = (u.pathname || '/').replace(/\/+$/, '') || '/';
        if (path === here && here !== '/') {
          link.setAttribute('aria-current', 'page');
          var owner = link.closest('#navigation ul > li');
          if (owner) { owner.classList.add('is-active'); }
        } else if (here === '/' && (path === '/' || path === '')) {
          link.setAttribute('aria-current', 'page');
        }
      } catch (err) { /* older browsers */ }
    });
  }());

  /* ---------------------------------------------------------------
     4. Search overlay
     --------------------------------------------------------------- */
  (function searchOverlay() {
    var layer = $('#st-search');
    if (!layer) { return; }
    var input = $('#st-search-input');
    var lastFocus = null;
    function open() {
      lastFocus = document.activeElement;
      body.classList.add('st-search-open', 'st-locked');
      layer.setAttribute('aria-hidden', 'false');
      if (input) { window.setTimeout(function () { input.focus(); }, 60); }
    }
    function close() {
      body.classList.remove('st-search-open');
      layer.setAttribute('aria-hidden', 'true');
      if (!body.classList.contains('st-drawer-open')) { body.classList.remove('st-locked'); }
      if (lastFocus && lastFocus.focus) { lastFocus.focus(); }
    }
    $$('[data-st-open="search"]').forEach(function (btn) { on(btn, 'click', open); });
    on($('#st-search-close'), 'click', close);
    on(layer, 'click', function (e) { if (e.target === layer) { close(); } });
    on(document, 'keydown', function (e) {
      if (!body.classList.contains('st-search-open')) { return; }
      if (e.key === 'Escape' || e.key === 'Esc') { close(); }
    });
    /* "/" focuses the visible search field when not typing */
    on(document, 'keydown', function (e) {
      if (e.key !== '/' || e.metaKey || e.ctrlKey || e.altKey) { return; }
      var t = e.target;
      if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.isContentEditable)) { return; }
      e.preventDefault();
      var field = $('#st-header-search');
      if (field && field.offsetParent !== null) { field.focus(); } else { open(); }
    });
  }());

  /* ---------------------------------------------------------------
     5. Announcement bar (dismissible)
     --------------------------------------------------------------- */
  (function announcement() {
    var bar = $('#st-announce');
    if (!bar) { return; }
    /* No gadget in the strip -> collapse it entirely */
    if (!bar.querySelector('.widget') || storageGet('st-announce') === 'off') {
      body.classList.add('st-announce-off');
      return;
    }
    var btn = $('#st-announce-close');
    on(btn, 'click', function () {
      body.classList.add('st-announce-off');
      storageSet('st-announce', 'off');
    });
  }());

  /* ---------------------------------------------------------------
     6. Reading progress + back to top (one passive scroll handler,
        rAF-throttled, transform-only so no layout is recalculated)
     --------------------------------------------------------------- */
  (function scrollUi() {
    var bar = $('#st-progress-bar');
    var top = $('#st-totop');
    if (!CFG.enableProgress) { body.classList.add('st-no-progress'); bar = null; }
    var ticking = false;

    function update() {
      ticking = false;
      var y = window.pageYOffset || root.scrollTop || 0;
      if (top) {
        if (y > 480) { top.classList.add('is-visible'); } else { top.classList.remove('is-visible'); }
      }
      if (bar && isItem) {
        var start = 0;
        var art = $('#st-article-body');
        if (art) { start = art.getBoundingClientRect().top + y; }
        var total = (document.documentElement.scrollHeight - start) - window.innerHeight;
        var done = y - start;
        var pct = total > 0 ? Math.min(1, Math.max(0, done / total)) : 0;
        bar.style.transform = 'scaleX(' + pct.toFixed(4) + ')';
      }
    }
    function request() {
      if (!ticking) { ticking = true; window.requestAnimationFrame(update); }
    }
    on(window, 'scroll', request, { passive: true });
    on(window, 'resize', request, { passive: true });
    update();

    on(top, 'click', function () {
      window.scrollTo({ top: 0, behavior: reduced ? 'auto' : 'smooth' });
      var s = $('.st-skip');
      if (s) { s.focus(); }
    });
  }());

  /* ---------------------------------------------------------------
     7. Post cards: move the first image into the media slot
        (Blogger has no reliable post-thumbnail data tag in classic
        templates, so the image is lifted from the post body itself —
        it is already in the HTML, so nothing extra is downloaded.)
     --------------------------------------------------------------- */
  (function cardImages() {
    $$('.pcard').forEach(function (card) {
      var media = $('.pcard__media', card);
      var excerpt = $('.pcard__excerpt', card);
      if (!media || !excerpt) { return; }
      var img = excerpt.querySelector('img');
      if (img) {
        img.removeAttribute('width');
        img.removeAttribute('height');
        img.removeAttribute('style');
        img.setAttribute('loading', 'lazy');
        img.setAttribute('decoding', 'async');
        if (img.alt === '') { img.removeAttribute('alt'); }
        if (!img.hasAttribute('alt')) {
          var t = $('.pcard__title', card);
          img.setAttribute('alt', t ? (t.textContent || '').trim() : '');
        }
        img.src = upgradeImage(img.getAttribute('src') || '');
        media.appendChild(img);
      } else {
        media.classList.add('is-empty');
      }
    });
  }());

  /* Blogger thumbnails arrive at 72px; ask the image service for a
     larger crop without changing the URL host. */
  function upgradeImage(src) {
    if (!src) { return src; }
    if (src.indexOf('/s72-c') > -1) { return src.replace('/s72-c', '/w640-h360-p-k-no-nu'); }
    if (src.indexOf('/s1600/') > -1) { return src.replace('/s1600/', '/w900/'); }
    return src;
  }

  /* ---------------------------------------------------------------
     8. Article enhancements (item pages)
     --------------------------------------------------------------- */
  (function article() {
    if (!isItem) { return; }
    var postBody = $('#st-article-body');
    if (!postBody) { return; }

    /* 8a. Reading time */
    var words = (postBody.textContent || '').trim().split(/\s+/).length;
    var mins = Math.max(1, Math.round(words / CFG.readingWpm));
    var slot = $('#st-readtime');
    if (slot) { slot.textContent = mins + ' min read'; }

    /* 8b. Featured image: lift the first image of the body into the
       figure above the text so the layout never depends on the author. */
    var figure = $('#st-article-media');
    var firstImg = postBody.querySelector('img');
    if (figure && firstImg) {
      firstImg.removeAttribute('style');
      firstImg.setAttribute('decoding', 'async');
      firstImg.setAttribute('fetchpriority', 'high');
      firstImg.src = upgradeImage(firstImg.getAttribute('src') || '');
      figure.insertBefore(firstImg, figure.firstChild);
      figure.hidden = false;
      var cap = firstImg.getAttribute('alt');
      var capEl = $('.st-article__caption', figure);
      if (cap && capEl) { capEl.textContent = cap; } else if (capEl) { capEl.remove(); }
    } else if (figure) {
      figure.remove();
    }

    /* 8c. Table of contents */
    if (CFG.enableToc) { buildToc(postBody); }

    /* 8d. Code blocks, tables, external links */
    $$('#st-article-body pre').forEach(function (pre) {
      if ($('.st-copybtn', pre)) { return; }
      var btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'st-copybtn';
      btn.textContent = 'Copy';
      on(btn, 'click', function () { copyText(pre.innerText || pre.textContent || '', btn); });
      pre.appendChild(btn);
    });
    $$('#st-article-body table').forEach(function (tbl) {
      if (tbl.parentNode && tbl.parentNode.className === 'st-tablewrap') { return; }
      var wrap = document.createElement('div');
      wrap.className = 'st-tablewrap';
      wrap.setAttribute('tabindex', '0');
      wrap.setAttribute('role', 'region');
      wrap.setAttribute('aria-label', 'Scrollable table');
      tbl.parentNode.insertBefore(wrap, tbl);
      wrap.appendChild(tbl);
    });
    $$('#st-article-body a[href^="http"]').forEach(function (link) {
      try {
        if (new URL(link.href).host !== window.location.host) {
          link.setAttribute('target', '_blank');
          link.setAttribute('rel', 'noopener');
        }
      } catch (err) { /* ignore */ }
    });
    $$('#st-article-body img').forEach(function (img) {
      img.setAttribute('loading', 'lazy');
      img.setAttribute('decoding', 'async');
    });

    /* 8e. Share links use the live URL, correctly encoded */
    var url = window.location.href;
    var title = (document.title || '').replace(/\s*\|.*$/, '');
    $$('[data-st-share]').forEach(function (a) {
      var net = a.getAttribute('data-st-share');
      var href = shareUrl(net, url, title);
      if (href) { a.setAttribute('href', href); }
    });
    var copyBtn = $('[data-st-share="copy"]');
    if (copyBtn) {
      on(copyBtn, 'click', function (e) { e.preventDefault(); copyText(url, copyBtn); });
    }

    /* 8f. Related posts from Blogger's own feed */
    if (CFG.enableRelated) { related(); }
  }());

  function shareUrl(net, url, title) {
    var u = encodeURIComponent(url);
    var t = encodeURIComponent(title);
    switch (net) {
      case 'whatsapp': return 'https://api.whatsapp.com/send?text=' + t + '%20' + u;
      case 'facebook': return 'https://www.facebook.com/sharer/sharer.php?u=' + u;
      case 'x': return 'https://twitter.com/intent/tweet?text=' + t + '&url=' + u;
      case 'telegram': return 'https://t.me/share/url?url=' + u + '&text=' + t;
      case 'linkedin': return 'https://www.linkedin.com/sharing/share-offsite/?url=' + u;
      default: return null;
    }
  }

  function copyText(text, btn) {
    var done = function () {
      if (!btn) { return; }
      var old = btn.getAttribute('data-label') || btn.textContent;
      btn.setAttribute('data-label', old);
      btn.textContent = 'Copied';
      window.setTimeout(function () { btn.textContent = btn.getAttribute('data-label') || old; }, 1800);
    };
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(done, function () { fallbackCopy(text, done); });
    } else {
      fallbackCopy(text, done);
    }
  }
  function fallbackCopy(text, done) {
    var ta = document.createElement('textarea');
    ta.value = text;
    ta.setAttribute('readonly', '');
    ta.style.position = 'fixed';
    ta.style.opacity = '0';
    document.body.appendChild(ta);
    ta.select();
    try { document.execCommand('copy'); done(); } catch (e) { /* nothing to do */ }
    document.body.removeChild(ta);
  }

  /* ---------------------------------------------------------------
     9. Table of contents — collapsible, keyboard friendly, and it
        never touches the article when there is nothing to list.
     --------------------------------------------------------------- */
  function buildToc(postBody) {
    var heads = $$('#st-article-body h2, #st-article-body h3');
    if (heads.length < CFG.minTocHeadings) { return; }
    var host = $('#st-toc');
    if (!host) { return; }

    var details = document.createElement('details');
    details.className = 'st-toc';
    details.open = !!(mqDesktop && mqDesktop.matches);
    var summary = document.createElement('summary');
    summary.textContent = 'In this article';
    details.appendChild(summary);

    var usedIds = {};
    var rootList = document.createElement('ol');
    var stack = [{ level: 2, list: rootList }];

    heads.forEach(function (h, n) {
      var id = h.id;
      if (!id) {
        id = 'section-' + (n + 1);
        var guard = 1;
        while (usedIds[id] || document.getElementById(id)) { id = 'section-' + (n + 1) + '-' + (++guard); }
        h.id = id;
      }
      usedIds[id] = true;
      var level = h.tagName === 'H3' ? 3 : 2;
      while (stack.length > 1 && stack[stack.length - 1].level > level) { stack.pop(); }
      if (level > stack[stack.length - 1].level) {
        var nested = document.createElement('ol');
        var lastLi = stack[stack.length - 1].list.lastElementChild;
        if (lastLi) { lastLi.appendChild(nested); stack.push({ level: level, list: nested }); }
      }
      var li = document.createElement('li');
      var a = document.createElement('a');
      a.href = '#' + h.id;
      a.textContent = (h.textContent || '').trim();
      a.setAttribute('data-toc-for', h.id);
      li.appendChild(a);
      stack[stack.length - 1].list.appendChild(li);
    });

    details.appendChild(rootList);
    host.appendChild(details);
    host.hidden = false;

    /* Highlight the section currently in view (IntersectionObserver
       only; no scroll polling). */
    if ('IntersectionObserver' in window) {
      var links = {};
      $$('.st-toc a[data-toc-for]').forEach(function (a) { links[a.getAttribute('data-toc-for')] = a; });
      var io = new IntersectionObserver(function (entries) {
        entries.forEach(function (entry) {
          var link = links[entry.target.id];
          if (!link) { return; }
          if (entry.isIntersecting) {
            $$('.st-toc a.is-current').forEach(function (x) { x.classList.remove('is-current'); });
            link.classList.add('is-current');
          }
        });
      }, { rootMargin: '-90px 0px -70% 0px', threshold: 0 });
      heads.forEach(function (h) { io.observe(h); });
    }
  }

  /* ---------------------------------------------------------------
     10. Same-origin Blogger feed helper
         Used only for the optional "Featured" rail and related
         posts. If the blog's site feed is switched off the sections
         stay hidden — nothing is faked.
     --------------------------------------------------------------- */
  function readFeed(label, max) {
    if (!window.fetch) { return Promise.resolve([]); }
    var base = (body.getAttribute('data-home') || '/') + 'feeds/posts/default';
    var url = label
      ? base + '/-/' + encodeURIComponent(label) + '?alt=json&max-results=' + max
      : base + '?alt=json&max-results=' + max;
    return fetch(url, { credentials: 'same-origin' })
      .then(function (r) { return r.ok ? r.json() : { feed: null }; })
      .then(function (json) {
        var entries = (json && json.feed && json.feed.entry) ? json.feed.entry : [];
        return entries.map(function (e) {
          var href = '';
          (e.link || []).forEach(function (l) { if (l.rel === 'alternate') { href = l.href; } });
          var thumb = e.media$thumbnail ? e.media$thumbnail.url : '';
          var author = (e.author && e.author[0] && e.author[0].name) ? e.author[0].name.$t : '';
          return {
            title: e.title ? e.title.$t : '',
            url: href,
            thumb: thumb ? thumb.replace(/\/s72-c/, '/w320-h240-p-k-no-nu') : '',
            date: e.published ? e.published.$t : '',
            author: author
          };
        }).filter(function (p) { return p.url && p.title; });
      })
      .catch(function () { return []; });
  }

  function fmtDate(iso) {
    if (!iso) { return ''; }
    var d = new Date(iso);
    if (isNaN(d.getTime())) { return ''; }
    var lang = (document.documentElement.getAttribute('lang') || 'en').slice(0, 2);
    try {
      return d.toLocaleDateString(lang, { day: 'numeric', month: 'short', year: 'numeric' });
    } catch (e) {
      return d.toISOString().slice(0, 10);
    }
  }

  function esc(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  function hcard(post) {
    var img = post.thumb
      ? '<div class="hcard__media"><img alt="" loading="lazy" decoding="async" src="' + esc(post.thumb) + '"></div>'
      : '';
    var when = fmtDate(post.date);
    return '<article class="hcard">' + img +
      '<div class="hcard__body"><h3 class="hcard__title"><a href="' + esc(post.url) + '">' +
      esc(post.title) + '</a></h3>' +
      '<p class="st-meta">' + (when ? '<span>' + esc(when) + '</span>' : '') + '</p></div>' +
      '</article>';
  }

  /* Compact card — used by the optional homepage "Featured" rail */
  function xcard(post) {
    var img = post.thumb
      ? '<div class="xcard__media"><img alt="" loading="lazy" decoding="async" src="' + esc(post.thumb) + '"></div>'
      : '';
    var when = fmtDate(post.date);
    return '<article class="xcard">' + img +
      '<div class="xcard__body"><h3 class="xcard__title"><a href="' + esc(post.url) + '">' +
      esc(post.title) + '</a></h3>' +
      '<p class="st-meta">' + (post.author ? '<span>' + esc(post.author) + '</span>' : '') +
      (when ? '<span aria-hidden="true" class="st-meta__dot">\u00b7</span><span>' + esc(when) + '</span>' : '') +
      '</p></div></article>';
  }

  function related() {
    var host = $('#st-related');
    if (!host) { return; }
    var labelLink = $('.st-labels a[href*="/search/label/"]');
    if (!labelLink) { return; }
    var label = decodeURIComponent((labelLink.getAttribute('href').split('/search/label/')[1] || '').split('?')[0]);
    if (!label) { return; }
    readFeed(label, CFG.relatedCount + 2).then(function (posts) {
      var here = window.location.href.split('?')[0];
      var list = posts.filter(function (p) { return p.url.split('?')[0] !== here; }).slice(0, CFG.relatedCount);
      if (!list.length) { return; }
      var rail = document.createElement('div');
      rail.className = 'st-rail';
      rail.innerHTML = list.map(hcard).join('');
      host.appendChild(rail);
      host.hidden = false;
    });
  }

  /* ---------------------------------------------------------------
     11. Optional homepage "Featured" rail
     --------------------------------------------------------------- */
  (function featured() {
    var host = $('#st-featured');
    if (!host || !CFG.enableFeatured || !CFG.featuredLabel) { return; }
    readFeed(CFG.featuredLabel, CFG.featuredCount).then(function (posts) {
      if (!posts.length) { return; }
      var rail = document.createElement('div');
      rail.className = 'st-rail st-rail--compact';
      rail.innerHTML = posts.map(xcard).join('');
      host.appendChild(rail);
      host.hidden = false;
    });
  }());

  /* ---------------------------------------------------------------
     12. Empty states — if Blogger returned no posts for this
         label/search/archive, say so plainly.
     --------------------------------------------------------------- */
  (function emptyStates() {
    var feed = $('.st-feed');
    if (!feed || feed.querySelector('.pcard')) { return; }
    if ($('.status-msg-wrap')) { return; }
    feed.innerHTML = '';
    var box = document.createElement('div');
    box.className = 'st-empty';
    box.style.gridColumn = '1 / -1';
    box.innerHTML = '<h2>Nothing published here yet</h2>' +
      '<p>This section is empty right now. Try another topic, or head back to the latest articles.</p>' +
      '<p><a class="st-btn st-btn--ghost st-btn--sm" href="' +
      esc(body.getAttribute('data-home') || '/') + '">Go to the homepage</a></p>';
    feed.appendChild(box);
  }());

  /* ---------------------------------------------------------------
     13. Small utilities
     --------------------------------------------------------------- */
  (function misc() {
    var year = $('#st-year');
    if (year) { year.textContent = String(new Date().getFullYear()); }

    var stamp = $('#st-today');
    if (stamp) {
      try {
        var lang = (document.documentElement.getAttribute('lang') || 'en').slice(0, 2);
        stamp.textContent = new Date().toLocaleDateString(lang, {
          weekday: 'long', day: 'numeric', month: 'long', year: 'numeric'
        });
      } catch (e) { /* leave the static text */ }
    }

    /* Lazy-load anything the author left eager, but never the LCP image */
    $$('.st-sidebar img, .st-footer img, #hero-aside img').forEach(function (img) {
      img.setAttribute('loading', 'lazy');
      img.setAttribute('decoding', 'async');
      if (img.getAttribute('src') && img.getAttribute('src').indexOf('/s72-c') > -1) {
        img.src = img.getAttribute('src').replace('/s72-c', '/w320-h240-p-k-no-nu');
      }
    });
  }());

}(window, document));
